import { writable } from 'svelte/store';
/**
 * This singleton's purpose is for caching stores only during a browser session.
 * It is disabled on the server.
 */
const stores = {};
const browser = () => typeof window !== 'undefined';
if (browser()) {
    window.addEventListener('storage', ({ key, newValue }) => {
        if (key === null) {
            return;
        }
        const store = stores[key];
        if (store !== undefined) {
            store.set(parse(newValue));
        }
    });
}
const getStorage = (type) => {
    return type === 'local' ? localStorage : sessionStorage;
};
const parse = (value) => {
    if (value === null) {
        return null;
    }
    try {
        return JSON.parse(value);
    }
    catch {
        return null;
    }
};
const createPersisted = (key, initialValue, storage) => {
    const initialOrStoredValue = parse(storage.getItem(key)) ?? initialValue;
    const store = writable(initialOrStoredValue);
    storage.setItem(key, JSON.stringify(initialOrStoredValue));
    const { subscribe, set } = store;
    return {
        set(value) {
            storage.setItem(key, JSON.stringify(value));
            set(value);
        },
        update(callback) {
            store.update((last) => {
                const value = callback(last);
                storage.setItem(key, JSON.stringify(value));
                return value;
            });
        },
        subscribe,
    };
};
/**
 * Creates a writable store that persists in localStorage
 *
 * @param key The storage key
 * @param initialValue The initial value to put in storage if no value exists.
 * @param storageType 'local' or 'session'
 */
export const persisted = (key, initialValue, storageType = 'local') => {
    if (!browser()) {
        return writable(initialValue);
    }
    const storage = getStorage(storageType);
    stores[key] ??= createPersisted(key, initialValue, storage);
    return stores[key];
};
